        (*raw_ev).sequence = xlib::XLastKnownRequestProcessed(conn.get_raw_dpy()) as u16;
        let mut dummy: xlib::XEvent = std::mem::zeroed();
        proc(
            conn.get_raw_dpy(),
            &mut dummy as *mut xlib::XEvent,
            raw_ev as *mut xlib::xEvent,
        );

